const input = $input.first().json || {};
const http = this.helpers.httpRequest.bind(this.helpers);

const CFG = {
  SUPABASE_URL: process.env.SUPABASE_URL || 'https://mbuljmpamdocnxppueww.supabase.co',
  SUPABASE_SERVICE_ROLE_KEY: process.env.SUPABASE_SERVICE_ROLE_KEY || '',
  EVOLUTION_BASE_URL: process.env.EVOLUTION_BASE_URL || 'https://whatsappapi.alopsi.com.br/',
  EVOLUTION_INSTANCE: process.env.EVOLUTION_INSTANCE || 'Celular_Emerson',
  EVOLUTION_API_KEY: process.env.EVOLUTION_API_KEY || '',
  REMINDER_DEFAULT_TIMEZONE: process.env.REMINDER_DEFAULT_TIMEZONE || 'America/Sao_Paulo',
  REMINDER_DEFAULT_HOUR: process.env.REMINDER_DEFAULT_HOUR || '20:00',
  REMINDER_WINDOW_MINUTES: Number(process.env.REMINDER_WINDOW_MINUTES || 14),
  REMINDER_QUERY_LIMIT: Number(process.env.REMINDER_QUERY_LIMIT || 1000)
};

const DEFAULT_WEEKDAYS = [0, 1, 2, 3, 4, 5, 6];
const WEEKDAY_MAP = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };

function normalizePhone(value) {
  return String(value || '').replace(/[^0-9]/g, '');
}

function circularMinuteDiff(a, b) {
  const diff = Math.abs(Number(a) - Number(b));
  return Math.min(diff, 1440 - diff);
}

function parseHourMinute(value, fallback) {
  const raw = String(value || fallback).trim();
  const match = raw.match(/^(\d{1,2})(?::(\d{2}))?$/);
  if (!match) return { hour: 20, minute: 0, label: fallback };

  const hour = Number(match[1]);
  const minute = match[2] === undefined ? 0 : Number(match[2]);

  if (!Number.isInteger(hour) || !Number.isInteger(minute)) return { hour: 20, minute: 0, label: fallback };
  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) return { hour: 20, minute: 0, label: fallback };

  const label = String(hour).padStart(2, '0') + ':' + String(minute).padStart(2, '0');
  return { hour, minute, label };
}

function parseWeekdays(rawValue) {
  if (Array.isArray(rawValue)) {
    const values = [...new Set(rawValue.map((v) => Number(v)).filter((v) => Number.isInteger(v) && v >= 0 && v <= 6))];
    return values.length ? values : [...DEFAULT_WEEKDAYS];
  }

  if (typeof rawValue === 'string') {
    const trimmed = rawValue.trim();
    if (!trimmed) return [...DEFAULT_WEEKDAYS];

    try {
      const parsed = JSON.parse(trimmed);
      if (Array.isArray(parsed)) return parseWeekdays(parsed);
    } catch (_) {}

    const lower = trimmed.toLowerCase();
    if (lower.includes('todos')) return [...DEFAULT_WEEKDAYS];
    if (lower.includes('seg') && lower.includes('sex')) return [1, 2, 3, 4, 5];

    const map = {
      domingo: 0, dom: 0,
      segunda: 1, 'segunda-feira': 1, seg: 1,
      terca: 2, 'terca-feira': 2, terça: 2, 'terça-feira': 2, ter: 2,
      quarta: 3, 'quarta-feira': 3, qua: 3,
      quinta: 4, 'quinta-feira': 4, qui: 4,
      sexta: 5, 'sexta-feira': 5, sex: 5,
      sabado: 6, sábado: 6, sab: 6, sáb: 6
    };

    const parts = lower.split(/\s*,\s*|\s+e\s+|\s*\/\s*/).map((p) => p.trim()).filter(Boolean);
    const values = [];

    for (const part of parts) {
      if (/^[0-7]$/.test(part)) {
        const n = part === '7' ? 0 : Number(part);
        if (!values.includes(n)) values.push(n);
        continue;
      }

      const mapped = map[part];
      if (mapped === undefined) continue;
      if (!values.includes(mapped)) values.push(mapped);
    }

    return values.length ? values : [...DEFAULT_WEEKDAYS];
  }

  return [...DEFAULT_WEEKDAYS];
}

function getLocalNowParts(timezone) {
  const now = new Date();
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone: timezone,
    weekday: 'short',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  });

  const parts = formatter.formatToParts(now);
  const index = new Map(parts.map((part) => [part.type, part.value]));
  const weekdayLabel = index.get('weekday') || 'Sun';

  return {
    weekday: WEEKDAY_MAP[weekdayLabel] ?? 0,
    hour: Number(index.get('hour') || 0),
    minute: Number(index.get('minute') || 0),
    localDate: (index.get('year') || '1970') + '-' + (index.get('month') || '01') + '-' + (index.get('day') || '01')
  };
}

function getLocalDateForTimestamp(isoDate, timezone) {
  if (!isoDate) return null;

  const dt = new Date(isoDate);
  if (Number.isNaN(dt.getTime())) return null;

  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: timezone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  });

  const parts = formatter.formatToParts(dt);
  const index = new Map(parts.map((part) => [part.type, part.value]));
  const year = index.get('year');
  const month = index.get('month');
  const day = index.get('day');

  if (!year || !month || !day) return null;
  return year + '-' + month + '-' + day;
}

async function httpJson(url, options) {
  const requestOptions = {
    method: options?.method || 'GET',
    url,
    headers: {
      'Content-Type': 'application/json',
      ...(options?.headers || {})
    },
    json: true
  };

  if (options && options.body !== undefined) {
    requestOptions.body = typeof options.body === 'string' ? JSON.parse(options.body) : options.body;
  }

  return await http(requestOptions);
}

async function supabase(path, options) {
  const baseUrl = String(CFG.SUPABASE_URL || '').replace(/\/+$/, '');
  const url = baseUrl + '/rest/v1/' + path;

  return await httpJson(url, {
    ...(options || {}),
    headers: {
      apikey: CFG.SUPABASE_SERVICE_ROLE_KEY,
      Authorization: 'Bearer ' + CFG.SUPABASE_SERVICE_ROLE_KEY,
      Prefer: options?.prefer || 'return=representation',
      ...(options?.headers || {})
    }
  });
}

async function sendWhatsApp(phone, text) {
  const baseUrl = String(CFG.EVOLUTION_BASE_URL || '').replace(/\/+$/, '');
  const url = baseUrl + '/message/sendText/' + CFG.EVOLUTION_INSTANCE;

  return await httpJson(url, {
    method: 'POST',
    headers: { apikey: CFG.EVOLUTION_API_KEY },
    body: { number: phone, text }
  });
}

async function logDispatch(row) {
  try {
    await supabase('whatsapp_reminder_dispatch_logs', { method: 'POST', body: row });
  } catch (_) {}
}

async function updateLastReminded(phone, isoTimestamp) {
  await supabase('whatsapp_reminder_preferences?phone=eq.' + encodeURIComponent(phone), {
    method: 'PATCH',
    body: {
      last_reminded_at: isoTimestamp,
      updated_at: isoTimestamp
    }
  });
}

function buildReminderMessage(localHourLabel) {
  return [
    '💜 Oi! Passando para lembrar do seu Diário Emocional.',
    '',
    'Leva menos de 2 minutos e pode te ajudar a perceber padrões com mais clareza.',
    '',
    'Quando quiser, envie *diário* para registrar.',
    '',
    '⏰ Lembrete configurado para: ' + localHourLabel
  ].join('\n');
}

if (!CFG.SUPABASE_URL || !CFG.SUPABASE_SERVICE_ROLE_KEY) {
  throw new Error('SUPABASE_URL e SUPABASE_SERVICE_ROLE_KEY são obrigatórios para o workflow agendado.');
}

if (!CFG.EVOLUTION_BASE_URL || !CFG.EVOLUTION_API_KEY || !CFG.EVOLUTION_INSTANCE) {
  throw new Error('Configuração Evolution incompleta para envio de lembretes.');
}

const summary = {
  scanned: 0,
  due: 0,
  sent: 0,
  skipped_weekday: 0,
  skipped_window: 0,
  skipped_duplicate: 0,
  skipped_invalid: 0,
  failed: 0
};

const selectPath = 'whatsapp_reminder_preferences?is_enabled=eq.true&select=phone,user_id,tenant_id,timezone,reminder_hour_local,reminder_weekdays,last_reminded_at,updated_at&limit=' + Math.max(1, Number(CFG.REMINDER_QUERY_LIMIT || 1000));
const rows = await supabase(selectPath, { method: 'GET' });
const preferences = Array.isArray(rows) ? rows : [];
summary.scanned = preferences.length;

for (const pref of preferences) {
  const phone = normalizePhone(pref.phone);
  if (!phone) {
    summary.skipped_invalid += 1;
    continue;
  }

  const timezone = String(pref.timezone || CFG.REMINDER_DEFAULT_TIMEZONE || 'America/Sao_Paulo').trim();

  let localParts;
  try {
    localParts = getLocalNowParts(timezone);
  } catch (_) {
    summary.skipped_invalid += 1;
    await logDispatch({
      phone,
      user_id: pref.user_id || null,
      tenant_id: pref.tenant_id || null,
      status: 'skipped_invalid_timezone',
      reason: 'invalid_timezone',
      metadata: { timezone },
      created_at: new Date().toISOString()
    });
    continue;
  }

  const target = parseHourMinute(pref.reminder_hour_local, CFG.REMINDER_DEFAULT_HOUR || '20:00');
  const weekdays = parseWeekdays(pref.reminder_weekdays);

  if (!weekdays.includes(localParts.weekday)) {
    summary.skipped_weekday += 1;
    continue;
  }

  const nowMinutes = localParts.hour * 60 + localParts.minute;
  const targetMinutes = target.hour * 60 + target.minute;
  const allowedWindow = Math.max(0, Number(CFG.REMINDER_WINDOW_MINUTES || 14));

  if (circularMinuteDiff(nowMinutes, targetMinutes) > allowedWindow) {
    summary.skipped_window += 1;
    continue;
  }

  const lastLocalDate = getLocalDateForTimestamp(pref.last_reminded_at, timezone);
  if (lastLocalDate && lastLocalDate === localParts.localDate) {
    summary.skipped_duplicate += 1;
    continue;
  }

  summary.due += 1;

  const nowIso = new Date().toISOString();
  try {
    await sendWhatsApp(phone, buildReminderMessage(target.label));
    await updateLastReminded(phone, nowIso);

    await logDispatch({
      phone,
      user_id: pref.user_id || null,
      tenant_id: pref.tenant_id || null,
      status: 'sent',
      timezone,
      local_date: localParts.localDate,
      local_hour_minute: String(localParts.hour).padStart(2, '0') + ':' + String(localParts.minute).padStart(2, '0'),
      target_hour_minute: target.label,
      metadata: { weekday: localParts.weekday, reminder_weekdays: weekdays },
      created_at: nowIso
    });

    summary.sent += 1;
  } catch (error) {
    summary.failed += 1;

    await logDispatch({
      phone,
      user_id: pref.user_id || null,
      tenant_id: pref.tenant_id || null,
      status: 'failed',
      reason: String(error?.message || 'send_failed').slice(0, 240),
      timezone,
      metadata: { weekday: localParts.weekday, reminder_weekdays: weekdays },
      created_at: nowIso
    });
  }
}

return [{
  json: {
    ok: true,
    executed_at: new Date().toISOString(),
    summary,
    trigger: input
  }
}];
